{
  "explanation": "A radian is the angle at the center of a circle created by an arc whose length equals the circle's radius. If you wrap the radius along the circumference, the central angle you get is exactly 1 radian. A full circle is 2π radians (about 6.28), which is why π appears throughout formulas involving angles and circles.",
  "manimCode": "const cx = -2.0;
const cy = 0.15;
const R = 2.25;

function arcVerts(radius, a0, a1, density) {
  const verts = [];
  const frac = Math.abs(a1 - a0) / (2 * Math.PI);
  const num = Math.max(4, Math.ceil((density || 64) * Math.max(frac, 0.01)));
  for (let i = 0; i <= num; i++) {
    const a = a0 + (a1 - a0) * (i / num);
    verts.push([cx + radius * Math.cos(a), cy + radius * Math.sin(a), 0]);
  }
  return verts;
}

const circle = new Circle({ radius: R, color: BLUE_B });
circle.moveTo([cx, cy, 0]);
circle.setStrokeWidth(2.5);

const centerDot = new Dot({ point: [cx, cy, 0], color: WHITE });
const oLabel = new Text({ text: 'O', color: GRAY, fontSize: 20 });
oLabel.moveTo([cx - 0.28, cy - 0.28, 0]);

const radius1 = new Polygon({
  vertices: [[cx, cy, 0], [cx + R, cy, 0]],
  color: YELLOW
});
radius1.setStrokeWidth(3).setFillOpacity(0);

const radius2 = new Polygon({
  vertices: [[cx, cy, 0], [cx + R, cy, 0]],
  color: YELLOW
});
radius2.setStrokeWidth(3).setFillOpacity(0);

const arc = new Polygon({
  vertices: arcVerts(R, 0, 0.01),
  color: GREEN
});
arc.setStrokeWidth(6).setFillOpacity(0);
arc.setOpacity(0);

const angleMarker = new Polygon({
  vertices: arcVerts(0.5, 0, 0.01, 32),
  color: ORANGE
});
angleMarker.setStrokeWidth(2.5).setFillOpacity(0);
angleMarker.setOpacity(0);

const endDotA = new Dot({ point: [cx + R, cy, 0], color: YELLOW });
const endDotB = new Dot({ point: [cx + R, cy, 0], color: YELLOW });

const rLabel = new Text({ text: 'r', color: YELLOW, fontSize: 28 });
rLabel.moveTo([cx + R * 0.5, cy - 0.4, 0]);

let arcLabel = new Text({ text: 'r', color: GREEN, fontSize: 28 });
arcLabel.moveTo([cx + (R + 0.4) * Math.cos(0.5), cy + (R + 0.4) * Math.sin(0.5), 0]);
arcLabel.setOpacity(0);

const title = new Text({ text: 'What is a Radian?', color: WHITE, fontSize: 36 });
title.moveTo([0, 3.45, 0]);

const formula = new MathTex({ latex: '\\theta = \\frac{s}{r} = \\frac{\\text{arc length}}{\\text{radius}}' });
await formula.waitForRender();
formula.scale(0.7);
formula.moveTo([3.35, 1.85, 0]);

let thetaReadout = new Text({ text: 'θ = 0.00 rad', color: ORANGE, fontSize: 26 });
thetaReadout.moveTo([3.35, 0.95, 0]);

let degReadout = new Text({ text: '= 0°', color: GRAY, fontSize: 22 });
degReadout.moveTo([3.35, 0.45, 0]);

let msg = new Text({ text: 'Drag the point or use the slider', color: GRAY, fontSize: 18 });
msg.moveTo([3.35, -0.15, 0]);

const note = new Text({ text: 'One radian: the angle where arc length equals radius', color: WHITE, fontSize: 20 });
note.moveTo([0, -3.15, 0]);

const note2 = new Text({ text: 'Full turn = 2π rad ≈ 6.28 rad = 360°', color: GRAY, fontSize: 18 });
note2.moveTo([0, -3.55, 0]);

const vt = new ValueTracker(0);

function updateGeometry(a) {
  const c = Math.cos(a);
  const s = Math.sin(a);
  const tip = [cx + R * c, cy + R * s, 0];
  radius2.setVertices([[cx, cy, 0], tip]);
  endDotB.moveTo(tip);
  if (a < 0.001) {
    arc.setVertices(arcVerts(R, 0, 0.001));
    angleMarker.setVertices(arcVerts(0.5, 0, 0.001, 32));
    arc.setOpacity(0);
    angleMarker.setOpacity(0);
  } else {
    arc.setVertices(arcVerts(R, 0, a));
    angleMarker.setVertices(arcVerts(0.5, 0, a, 32));
    arc.setOpacity(1);
    angleMarker.setOpacity(1);
  }
}

function updateLabels(a) {
  const posT = thetaReadout.getCenter();
  scene.remove(thetaReadout);
  thetaReadout = new Text({ text: 'θ = ' + a.toFixed(2) + ' rad', color: ORANGE, fontSize: 26 });
  thetaReadout.moveTo(posT);
  scene.add(thetaReadout);

  const posD = degReadout.getCenter();
  scene.remove(degReadout);
  const deg = a * 180 / Math.PI;
  degReadout = new Text({ text: '= ' + deg.toFixed(1) + '°', color: GRAY, fontSize: 22 });
  degReadout.moveTo(posD);
  scene.add(degReadout);

  const mid = a / 2;
  const lr = R + 0.4;
  scene.remove(arcLabel);
  if (Math.abs(a - 1) < 0.04) {
    arcLabel = new Text({ text: 'r', color: GREEN, fontSize: 28 });
  } else if (a < 0.05) {
    arcLabel = new Text({ text: '', color: GREEN, fontSize: 28 });
  } else {
    arcLabel = new Text({ text: 's = θ·r', color: GREEN, fontSize: 22 });
  }
  arcLabel.moveTo([cx + lr * Math.cos(mid), cy + lr * Math.sin(mid), 0]);
  scene.add(arcLabel);

  const posM = msg.getCenter();
  scene.remove(msg);
  if (Math.abs(a - 1) < 0.04) {
    msg = new Text({ text: '★ arc length = radius!', color: GREEN, fontSize: 20 });
  } else {
    msg = new Text({ text: 'Drag the point or use the slider', color: GRAY, fontSize: 18 });
  }
  msg.moveTo(posM);
  scene.add(msg);
}

radius2.addUpdater(() => {
  updateGeometry(vt.getValue());
});

scene.add(title, note, note2);
await scene.play(new AnimationGroup([new Create(circle), new FadeIn(centerDot), new FadeIn(oLabel)]));
await scene.play(new AnimationGroup([new Create(radius1), new FadeIn(endDotA), new FadeIn(rLabel)]));
scene.add(radius2, endDotB, arc, angleMarker, arcLabel);
scene.add(formula, thetaReadout, degReadout, msg);

await scene.play(vt.animateTo(1));
updateLabels(1);

makeHoverable(endDotB, scene, { hoverScale: 1.4, hoverColor: WHITE });
makeDraggable(endDotB, scene, {
  onDrag: (mob) => {
    const p = mob.getCenter();
    let a = Math.atan2(p[1] - cy, p[0] - cx);
    if (a < 0) a += 2 * Math.PI;
    vt.setValue(a);
    updateLabels(a);
  }
});

const controls = new Controls(scene, { position: 'bottom-right', width: 260 });
controls.addSlider({
  label: 'θ (radians)',
  min: 0,
  max: 2 * Math.PI,
  value: 1,
  step: 0.01,
  onChange: (val) => {
    vt.setValue(val);
    updateLabels(val);
  }
});
controls.addButton({
  label: 'Reset to 1 rad',
  onClick: () => {
    vt.setValue(1);
    updateLabels(1);
  }
});

await scene.wait(999999);"
